/**
* User account model containing properties related to a user's account.
* @param about Profile about description.
* @param accountUnderscoretype Type of account
* @param boardUnderscorecount   User account board count.   **Note**: Board count on user account level may differ from counts found elsewhere due to attribution of collaborative Boards.
* @param businessUnderscorename 
* @param followerUnderscorecount User account follower count.
* @param followingUnderscorecount User account following count.
* @param id User account ID.
* @param monthlyUnderscoreviews User account monthly views.
* @param pinUnderscorecount User account pin count. This includes both created and saved pins.
* @param profileUnderscoreimage 
* @param username 
* @param websiteUnderscoreurl 
*/

case class Account(
  about: Option[String],
  accountUnderscoretype: Option[UserAccountType],
  boardUnderscorecount: Option[Int],
  businessUnderscorename: Option[String],
  followerUnderscorecount: Option[Int],
  followingUnderscorecount: Option[Int],
  id: Option[Refined[String, MatchesRegex["^\\d+$"]]],
  monthlyUnderscoreviews: Option[Int],
  pinUnderscorecount: Option[Int],
  profileUnderscoreimage: Option[String],
  username: Option[String],
  websiteUnderscoreurl: Option[String]
)
object Account {
  implicit val encoderAccount: Encoder[Account] = deriveEncoder[Account].mapJson(_.dropNullValues)
  implicit val decoderAccount: Decoder[Account] = deriveDecoder[Account]
}

/**
* 
* @param adUnderscoreaccountUnderscoreid ID of the Ad Account that owns the template
* @param adUnderscoreaccountUnderscoreids IDs of the Ad Accounts that have access to this template
* @param adeUnderscorecolumns A list of ADE columns
* @param attributionUnderscoretype Attribution type for Brand/Category/SKU reports
* @param clickUnderscorewindowUnderscoredays The length of the sliding window over which click conversions will be attributed
* @param columns A list of columns to be included in the report
* @param conversionUnderscorereportUnderscoretimeUnderscoretype Conversion report time type
* @param creationUnderscoresource The surface used to create this template
* @param customUnderscorecolumnUnderscoreids A list of custom column IDs
* @param displayUnderscoremetadata Additional metadata about this reporting template
* @param engagementUnderscorewindowUnderscoredays The length of the sliding window over which engagement conversions will be attributed
* @param filtersUnderscorejson A JSON representation of any filters to be applied before returning report data. Each filter object should contain all of the following fields:\\ \"field\": The column name\\ \"operator\": The operator. Allowed operators: [\"=\", \"!=\", \"in\", \"not_in\", \"~\", \">\", \"<\", \"contains_substring\"]\\ \"value\": A single value or a list of values
* @param granularity 
* @param id Template ID
* @param ingestionUnderscoresources The filter on the conversion ingestion source method for conversion metrics
* @param isUnderscoredefault A boolean representing if this is the default view that loads for this template type
* @param isUnderscoredeleted A boolean that indicates if the template has been deleted
* @param isUnderscoreownedUnderscorebyUnderscoreuser A boolean value that indicates if the user owns the template
* @param isUnderscorescheduled A boolean value that indicates if this template has been used to create a scheduled report
* @param name Template Name
* @param reportUnderscoreendUnderscorerelativeUnderscoredaysUnderscoreinUnderscorepast The number of days prior to the day the report will be delivered at which the report will end
* @param reportUnderscoreformat 
* @param reportUnderscorelevel 
* @param reportUnderscorestartUnderscorerelativeUnderscoredaysUnderscoreinUnderscorepast The number of days prior to the day the report will be delivered at which the report will start
* @param reportingUnderscoretimeUnderscorezone Timezone for reporting data
* @param sortUnderscoreby Unified metric sort configuration
* @param `type` Type of the template
* @param updatedUnderscoretime Time of last update in seconds since Unix epoch
* @param userUnderscoreid ID of the user who created the template
* @param viewUnderscorewindowUnderscoredays The length of the sliding window over which view conversions will be attributed
*/

case class AccountTemplate(
  adUnderscoreaccountUnderscoreid: Option[String],
  adUnderscoreaccountUnderscoreids: Option[List[String]],
  adeUnderscorecolumns: Option[List[String]],
  attributionUnderscoretype: Option[AnyType],
  clickUnderscorewindowUnderscoredays: Option[BigDecimal],
  columns: Option[List[ReportingColumn]],
  conversionUnderscorereportUnderscoretimeUnderscoretype: Option[ConversionReportTimeType],
  creationUnderscoresource: Option[CreationSource],
  customUnderscorecolumnUnderscoreids: Option[List[String]],
  displayUnderscoremetadata: Option[String],
  engagementUnderscorewindowUnderscoredays: Option[BigDecimal],
  filtersUnderscorejson: Option[String],
  granularity: Option[Granularity],
  id: String,
  ingestionUnderscoresources: Option[List[IngestionSource]],
  isUnderscoredefault: Option[Boolean],
  isUnderscoredeleted: Option[Boolean],
  isUnderscoreownedUnderscorebyUnderscoreuser: Option[Boolean],
  isUnderscorescheduled: Option[Boolean],
  name: Option[String],
  reportUnderscoreendUnderscorerelativeUnderscoredaysUnderscoreinUnderscorepast: Option[BigDecimal],
  reportUnderscoreformat: Option[DataOutputFormat],
  reportUnderscorelevel: Option[MetricsReportingLevel],
  reportUnderscorestartUnderscorerelativeUnderscoredaysUnderscoreinUnderscorepast: Option[BigDecimal],
  reportingUnderscoretimeUnderscorezone: Option[ReportingTimeZone],
  sortUnderscoreby: Option[AnyType],
  `type`: Option[String],
  updatedUnderscoretime: Option[BigDecimal],
  userUnderscoreid: Option[String],
  viewUnderscorewindowUnderscoredays: Option[BigDecimal]
)
object AccountTemplate {
  implicit val encoderAccountTemplate: Encoder[AccountTemplate] = deriveEncoder[AccountTemplate].mapJson(_.dropNullValues)
  implicit val decoderAccountTemplate: Decoder[AccountTemplate] = deriveDecoder[AccountTemplate]
}

/**
* Ad group billable event type. For update, only draft ad groups may update billable event.
*/

object ActionType extends Enumeration {
    type ActionType = Value
    val CLICKTHROUGH = Value
    val IMPRESSION = Value
    val VIDEO_V_50_MRC = Value
    implicit val decoder: Decoder[ActionType.Value] = Decoder.decodeEnumeration(ActionType)
    implicit val encoder: Encoder[ActionType.Value] = Encoder.encodeEnumeration(ActionType)
}

/**
* 
* @param adUnderscoreaccountUnderscoreid The ID of the advertiser that this ad belongs to.
* @param adUnderscoregroupUnderscoreid ID of the ad group that contains the ad.
* @param androidUnderscoredeepUnderscorelink Deep link URL for Android devices.
* @param campaignUnderscoreid ID of the ad campaign that contains this ad.
* @param carouselUnderscoreandroidUnderscoredeepUnderscorelinks Comma-separated deep links for the carousel pin on Android.
* @param carouselUnderscoredestinationUnderscoreurls Comma-separated destination URLs for the carousel pin to promote.
* @param carouselUnderscoreiosUnderscoredeepUnderscorelinks Comma-separated deep links for the carousel pin on iOS.
