/**
* 
* @param attributes 
* @param itemUnderscoreid Catalog item id in the merchant namespace
* @param operation 
* @param storeUnderscorecode Store code for the local inventory item
*/
sealed trait LocalInventoryOperation
object LocalInventoryOperation {
  import io.circe.{ Decoder, Encoder }
  import io.circe.syntax._
  import cats.syntax.functor._

// use discriminator mapping
  implicit val localInventoryOperationEncoder: Encoder[LocalInventoryOperation] = Encoder.instance {
    case localInventoryCreateOperation: LocalInventoryCreateOperation => localInventoryCreateOperation.asJson.mapObject(("operation" -> "CREATE".asJson) +: _)
    case localInventoryDeleteOperation: LocalInventoryDeleteOperation => localInventoryDeleteOperation.asJson.mapObject(("operation" -> "DELETE".asJson) +: _)
    case localInventoryUpdateOperation: LocalInventoryUpdateOperation => localInventoryUpdateOperation.asJson.mapObject(("operation" -> "UPDATE".asJson) +: _)
    case localInventoryUpsertOperation: LocalInventoryUpsertOperation => localInventoryUpsertOperation.asJson.mapObject(("operation" -> "UPSERT".asJson) +: _)
  }

  implicit val localInventoryOperationDecoder: Decoder[LocalInventoryOperation] = Decoder.instance { cursor =>
    cursor.downField("operation").as[String].flatMap {
      case "CREATE" =>
        cursor.as[LocalInventoryCreateOperation]
      case "DELETE" =>
        cursor.as[LocalInventoryDeleteOperation]
      case "UPDATE" =>
        cursor.as[LocalInventoryUpdateOperation]
      case "UPSERT" =>
        cursor.as[LocalInventoryUpsertOperation]
    }
  }
}


