/**
* Notification request body. Can be either a batch of notification objects or a single notification object.
*/
sealed trait NotificationPostRequest
object NotificationPostRequest {
  import io.circe.{ Decoder, Encoder }
  import io.circe.syntax._
  import cats.syntax.functor._

// no discriminator
  implicit val notificationPostRequestEncoder: Encoder[NotificationPostRequest] = Encoder.instance {
    case list_Object: List[Object] => list_Object.asJson
    case `object`: Object => `object`.asJson
  }

  implicit val notificationPostRequestDecoder: Decoder[NotificationPostRequest] =
    List[Decoder[NotificationPostRequest]](
      Decoder[List[Object]].widen,
      Decoder[Object].widen,
  ).reduceLeft(_ or _)
}


